import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Login = () => {

    const navigate = useNavigate();

    const [role, setRole] = useState('');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleLogin = (e) => {

        e.preventDefault();

        console.log({
            role,
            email,
            password,
        });

        alert(`${role} Login Successful`);

        if (role === 'admin') {
            navigate('/admin');
        } else {
            navigate('/');
        }
    };

    return (

        <div className="container">

            <form
                className="form"
                onSubmit={handleLogin}
            >

                <h1>Login</h1>

                <select
                    value={role}
                    onChange={(e) =>
                        setRole(e.target.value)
                    }
                >
                    <option value="">
                        Select Role
                    </option>

                    <option value="user">
                        User
                    </option>

                    <option value="admin">
                        Admin
                    </option>
                </select>

                <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) =>
                        setEmail(e.target.value)
                    }
                />

                <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) =>
                        setPassword(e.target.value)
                    }
                />

                <button type="submit">
                    Login
                </button>

                <p onClick={() => navigate('/signup')}>
                    Create Account
                </p>

            </form>

        </div>
    );
};

export default Login;
